import { existsSync, readFileSync } from 'node:fs';
import { join } from 'node:path';

import { afterEach, beforeEach, describe, expect, it } from 'vitest';

import { createLifecycleFixture, type LifecycleFixture } from './fixtures/lifecycle-canonical.js';
import { getPhaseGuidance } from '../guidance.js';

// Historical P3 identities are intentionally kept verbatim. The legacy P3 suite
// hoists PlaywrightAdapter mocks, so these canonical MCP/SQLite/Chromium checks
// run in a separate test module with the production DiscoveryHandler.
describe('P3 Suite de Verificación MCP (T3 - T15)', () => {
  let f: LifecycleFixture;
  const cleanup: Array<() => Promise<void>> = [];
  beforeEach(async () => { f = await createLifecycleFixture(close => cleanup.push(close)); });
  afterEach(async () => {
    const results = await Promise.allSettled(cleanup.splice(0).map(close => close()));
    for (const item of results) if (item.status === 'rejected') throw item.reason;
  });

  it('T6: qap_discover éxito: no contiene "Descubrir otro módulo", "pregunta_doc" ni "opciones_doc"; siguiente_accion tipo entrevista_vista (<= 5 preguntas) con tool qap_rules_set, categorias_aplicables y rutas_detectadas_fuera_del_plan', async () => {
    await f.working(['catalog', 'orders']);
    const discovered = await f.discover();
    expect(discovered).toMatchObject({
      status_scope: 'acquisition', mode: 'fresh_anonymous_static',
      acquisition_status: 'completed', module_identity_status: 'resolved',
      association_status: 'confirmed', persistence: 'committed',
      counts: { views: expect.any(Number), forms: expect.any(Number) },
    });
    expect(JSON.stringify(discovered)).not.toMatch(/Descubrir otro módulo|pregunta_doc|opciones_doc/);
    expect(discovered).not.toHaveProperty('siguiente_accion');
    expect((await f.knowledge.query(f.scope.applicationId, 'requirement')).items).toHaveLength(0);
    const next = await f.interview('catalog', { action: 'next' });
    expect(next).toMatchObject({ status: 'interviewing', question: {
      module: 'catalog', category: 'proposito', human_review_required: true,
    } });
    expect(await f.call('qap_status')).toMatchObject({ siguiente_accion: {
      tipo: 'trabajo', tool: 'qap_rules_set', module: 'catalog',
      canonical_interview: { action: 'next' },
    } });
    f.integrity();
  });

  it('T7: rules.yaml tras discover: reglas inferred/dom con ids deterministas; re-discover idempotente (sin duplicados, reglas confirmadas intactas)', async () => {
    await f.working();
    await f.discover();
    const first = (await f.knowledge.query(f.scope.applicationId, 'observation')).items;
    expect(first.length).toBeGreaterThan(0);
    expect(new Set(first.map(item => item.entity.id)).size).toBe(first.length);
    const question = (await f.interview('catalog', { action: 'next' })).question;
    await f.confirm('catalog', question, f.proposal);
    const requirements = (await f.knowledge.query(f.scope.applicationId, 'requirement')).items;
    expect(requirements).toHaveLength(1);
    const recorded = await f.knowledge.history(f.scope.applicationId, 'requirement', requirements[0].entity.id);
    await f.discover();
    const all = (await f.knowledge.query(f.scope.applicationId, 'observation')).items;
    expect(all.length).toBeGreaterThan(first.length);
    expect(new Set(all.map(item => item.entity.id)).size).toBe(all.length);
    for (const observed of first) expect(all.some(item => item.entity.id === observed.entity.id)).toBe(true);
    expect((await f.knowledge.query(f.scope.applicationId, 'requirement')).items).toEqual(requirements);
    expect(await f.knowledge.history(f.scope.applicationId, 'requirement', requirements[0].entity.id)).toEqual(recorded);
    expect(existsSync(join(f.root, '.qa', 'modules', 'catalog', 'rules.yaml'))).toBe(false);
    f.integrity();
  });

  it('T9: Fallo de Playwright: no inserta reglas; siguiente_accion tipo decision', async () => {
    await f.working();
    // An explicitly invalid browser binary tests the real acquisition failure
    // rather than the removed PlaywrightAdapter mock or a fabricated success.
    await f.restart(true, ['catalog', 'orders'], { executable_path: join(f.root, 'missing-chromium-binary') });
    const before = readFileSync(f.lifecyclePath, 'utf8');
    const failure = await f.call('qap_discover', { name: 'catalog', path: '/catalog' });
    expect(failure.status).not.toBe('completed');
    expect(failure).toMatchObject({ persistence: 'not_attempted', association_status: 'not_attempted' });
    expect((await f.knowledge.query(f.scope.applicationId, 'observation')).items).toHaveLength(0);
    expect((await f.knowledge.query(f.scope.applicationId, 'requirement')).items).toHaveLength(0);
    expect(readFileSync(f.lifecyclePath, 'utf8')).toBe(before);
    expect(existsSync(join(f.root, '.qa', 'modules', 'catalog', 'rules.yaml'))).toBe(false);
    f.integrity();
  });

  it('T14: qap_status WORKING: (a) observed con hipótesis reanuda entrevista; (b) interviewing incompleto reanuda; (c) planned elige high > medium > low luego orden; (d) todos completos tipo decision', async () => {
    // Plan order is intentionally NOT priority order: high must win over medium and low.
    await f.working(['orders', 'dashboard', 'catalog'], {
      orders: 'low', dashboard: 'medium', catalog: 'high',
    });
    expect(await f.call('qap_status')).toMatchObject({ siguiente_accion: {
      tipo: 'trabajo', tool: 'qap_discover', module: 'catalog',
    } });
    await f.discover();
    // Canonical Discovery records observations but does not mutate legacy lifecycle.
    expect(f.lifecycle().modules.catalog.state).toBe('planned');
    expect(await f.call('qap_status')).toMatchObject({ siguiente_accion: {
      tipo: 'trabajo', tool: 'qap_discover', module: 'catalog',
    } });
    const question = await f.interview('catalog', { action: 'next' });
    expect(question).toMatchObject({ status: 'interviewing', question: {
      module: 'catalog', human_review_required: true,
    } });
    expect(await f.call('qap_status')).toMatchObject({ siguiente_accion: {
      tipo: 'trabajo', tool: 'qap_rules_set', module: 'catalog',
      canonical_interview: { action: 'next' },
    } });
    await f.ready();
    expect(await f.call('qap_status')).toMatchObject({ siguiente_accion: { tool: 'qap_rules_set', module: 'catalog' } });
    expect(await f.approvedClosure('catalog', { action: 'close' })).toMatchObject({ status: 'closed' });
    const next = await f.call('qap_status');
    expect(next).toMatchObject({ siguiente_accion: {
      tipo: 'trabajo', tool: 'qap_discover', module: 'dashboard',
    } });
    expect(next.siguiente_accion.descripcion).toContain('dashboard');
    expect(f.lifecycle().modules.catalog.state).toBe('closed');
    expect(f.lifecycle().modules.dashboard.state).toBe('planned');
    expect(f.lifecycle().modules.orders.state).toBe('planned');

    // Pure guidance verifies stable plan order when two planned modules share priority.
    const commonPlan = [
      { module: 'orders', path: '/orders', priority: 'medium', status: 'pending' },
      { module: 'dashboard', path: '/dashboard', priority: 'medium', status: 'pending' },
      { module: 'catalog', path: '/catalog', priority: 'low', status: 'pending' },
    ];
    expect(getPhaseGuidance('WORKING', {
      plan: commonPlan,
      modules: { orders: { state: 'planned' }, dashboard: { state: 'planned' }, catalog: { state: 'planned' } },
    }).siguiente_accion).toMatchObject({ tipo: 'trabajo', tool: 'qap_discover', module: 'orders' });
  });

  it('T15: E2E: flujo de P2 hasta WORKING -> discover A -> rules_set parcial -> status (reanuda A) -> rules_set completa cobertura -> status (propone B) -> discover B; ninguna respuesta del flujo contiene texto del bucle', async () => {
    const forbidden = /botones interactivos en modal|No respondas con listas|modal interactivo|prohibido usar listas/i;
    const init = await f.working(['catalog', 'orders']);
    expect(JSON.stringify(init)).not.toMatch(forbidden);
    const first = await f.discover('catalog');
    expect(JSON.stringify(first)).not.toMatch(forbidden);
    const question = await f.interview('catalog', { action: 'next' });
    expect(JSON.stringify(question)).not.toMatch(forbidden);
    const pending = await f.call('qap_status');
    expect(pending).toMatchObject({ siguiente_accion: { tool: 'qap_rules_set', module: 'catalog' } });
    expect(JSON.stringify(pending)).not.toMatch(forbidden);
    await f.ready();
    expect((await f.close('catalog', { action: 'evaluate' })).assessment)
      .toMatchObject({ specification_coverage: { status: 'complete' }, execution_coverage: { status: 'not_executed' } });
    expect(await f.approvedClosure('catalog', { action: 'close' })).toMatchObject({ status: 'closed' });
    const next = await f.call('qap_status');
    expect(next).toMatchObject({ siguiente_accion: { tool: 'qap_discover' } });
    expect(next.siguiente_accion.descripcion).toContain('orders');
    const second = await f.discover('orders');
    expect(JSON.stringify([next, second])).not.toMatch(forbidden);
    expect((await f.knowledge.query(f.scope.applicationId, 'requirement')).items).toHaveLength(1);
    expect((await f.knowledge.query(f.scope.applicationId, 'observation')).items.length).toBeGreaterThan(0);
    expect(f.lifecycle().modules.orders.state).toBe('planned');
    f.integrity();
  });
});

import { readFileSync } from 'node:fs';
import { isSubstantiveRuleText, normalizeSlug } from '@qap/shared';
import { afterEach, describe, expect, it } from 'vitest';
import { createLifecycleFixture, type LifecycleFixture } from './fixtures/lifecycle-canonical.js';

// Stable nested historical fullNames; canonical tests have no hoisted adapter mocks.
describe('P4.5-A.2 Suite de Integridad y Verificación (C1, C2, C3, C4, C6, C9, C10)', () => {
  const cleanup: Array<() => Promise<void>> = [];
  const fixture = (html?: string): Promise<LifecycleFixture> => createLifecycleFixture(close => cleanup.push(close), html);
  afterEach(async () => {
    const settled = await Promise.allSettled(cleanup.splice(0).map(close => close()));
    for (const v of settled) if (v.status === 'rejected') throw v.reason;
  });
  describe('C3: Integridad de categoría en from_option y regla de cobertura completa', () => {
    it('C3-a: la categoría de from_option se toma siempre de la pregunta pendiente persistida', async () => {
      const f = await fixture();
      await f.working();
      const q = (await f.interview('catalog', { action: 'next' })).question;
      expect(q.category).toBe('proposito');
      // Interview category is a question prompt; formal requirement classification is explicit.
      const proposal = { ...f.proposal, category: 'security' as const };
      const p = await f.interview('catalog', { action: 'propose', question_id: q.id,
        version: q.version, expected_revision: 0, proposal });
      expect(p).toMatchObject({ status: 'pending_review', question: { id: q.id, category: 'proposito' } });
      expect((await f.knowledge.query(f.scope.applicationId, 'requirement')).items).toHaveLength(0);
      const review = { action: 'review' as const, question_id: q.id, version: p.question.version };
      expect(await f.interview('catalog', review)).toMatchObject({
        status: 'blocked', code: 'human_review_not_authorized',
      });
      const request = f.inbox.interviews.at(-1)!;
      expect(request.proposal.category).toBe('security');
      f.inbox.approveInterview(request);
      const accepted = await f.interview('catalog', review);
      expect(accepted).toMatchObject({ status: 'confirmed', revision: 1 });
      const saved = await f.knowledge.get(f.scope.applicationId, 'requirement', accepted.requirement_id);
      expect(saved?.entity).toMatchObject({
        category: 'security', validation_status: 'confirmed', provenance: 'developer_interview',
      });
      expect(saved?.trace).toMatchObject({ source: 'canonical_interview_v1',
        reason: request.requestDigest, review: 'reviewed' });
      f.integrity();
    });

    it('C3-b: si la petición declara una categoría distinta a la de la pregunta pendiente se rechaza con blocked', async () => {
      const f=await fixture();await f.working();const q=(await f.interview('catalog',{action:'next'})).question;expect(await f.interview('catalog',{action:'review',question_id:'invented-actor',version:q.version})).toMatchObject({status:'blocked',code:'unknown_question'});expect(await f.interview('orders',{action:'propose',question_id:q.id,version:q.version,expected_revision:0,proposal:f.proposal})).toMatchObject({status:'blocked'});expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);
    });
  });

  describe('C4: Flujo de respuestas cortas como borrador y propuesta de enunciado', () => {
    it('C4-a: respuesta corta se guarda como borrador (status inferred, source user_text, borrador true) y no cubre', async () => {
      const f=await fixture();await f.working();const q=(await f.interview('catalog',{action:'next'})).question;expect(await f.interview('catalog',{action:'propose',question_id:q.id,version:q.version,expected_revision:0,proposal:{...f.proposal,title:'Gestión compras'}})).toMatchObject({status:'pending_review'});const draft=f.drafts();expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);await f.restart();expect(f.drafts()).toEqual(draft);const next=(await f.interview('catalog',{action:'next'})).question;expect(next.id).toBe(q.id);expect(await f.interview('catalog',{action:'review',question_id:q.id,version:next.version})).toMatchObject({status:'blocked',code:'substantive_statement_required'});
    });

    it('C4-b: derivación determinista en categoría actor que nombra roles emite Pregunta una_opcion directamente', async () => {
      const f=await fixture();await f.working();const first=(await f.interview('catalog',{action:'next'})).question;await f.confirm('catalog',first,f.proposal);const actor=(await f.interview('catalog',{action:'next'})).question;expect(actor).toMatchObject({module:'catalog',category:'actor',human_review_required:true});expect(actor.options.map(o=>o.id)).toEqual(['propose','correct','defer','review']);expect((await f.interview('catalog',{action:'next'})).question).toEqual(actor);expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(1);
    });

    it('C4-c: envío de propuesta_enunciado válida para un borrador emite Pregunta una_opcion con las 3 opciones', async () => {
      const f=await fixture();await f.working();const q=(await f.interview('catalog',{action:'next'})).question;const p=await f.interview('catalog',{action:'propose',question_id:q.id,version:q.version,expected_revision:0,proposal:f.proposal});expect(p).toMatchObject({status:'pending_review',question:{id:q.id,human_review_required:true}});expect(p.question.options.map(o=>o.id)).toEqual(['propose','correct','defer','review']);expect(await f.interview('catalog',{action:'review',question_id:q.id,version:p.question.version})).toMatchObject({status:'blocked',code:'human_review_not_authorized'});expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);
    });

    it('C4-d: resolver con "Es correcto" guarda regla confirmed user_confirmed con enunciado exacto y cubre', async () => {
      const f = await fixture();
      await f.working();
      const q = (await f.interview('catalog', { action: 'next' })).question;
      const approved = await f.confirm('catalog', q, f.proposal);
      expect(approved.result).toMatchObject({ status: 'confirmed', revision: 1 });
      const req = (await f.knowledge.query(f.scope.applicationId, 'requirement')).items;
      expect(req).toHaveLength(1);
      expect(req[0].entity).toMatchObject({ title: f.proposal.title, description: f.proposal.description,
        category: 'functional', validation_status: 'confirmed', provenance: 'developer_interview' });
      const saved = await f.knowledge.get(f.scope.applicationId, 'requirement', req[0].entity.id);
      expect(saved?.trace).toMatchObject({ source: 'canonical_interview_v1', review: 'reviewed',
        reason: expect.any(String) });
      const receipts = (await f.knowledge.query(f.scope.applicationId, 'relation')).items
        .filter(item => item.trace.source === 'human_review_authorization_v1');
      expect(receipts).toHaveLength(1);
      expect(receipts[0].trace).toMatchObject({ reason: saved?.trace.reason, review: 'reviewed' });
      expect(receipts[0].entity).toMatchObject({ predicate: 'related_to',
        target: { kind: 'requirement', id: req[0].entity.id, revision: 1 } });
      expect((await f.close('catalog', { action: 'evaluate' })).assessment.execution_coverage.status)
        .toBe('not_executed');
      f.integrity();
    });

    it('C4-e: resolver con "Lo defino después" guarda regla deferred y no cubre', async () => {
      const f=await fixture();await f.working();const q=(await f.interview('catalog',{action:'next'})).question;const d=await f.interview('catalog',{action:'defer',question_id:q.id,version:q.version});expect(d).toMatchObject({status:'deferred',question:{state:'deferred'}});expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);await f.restart();expect((await f.interview('catalog',{action:'next'})).question).toMatchObject({id:q.id,state:'deferred'});expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);
    });

    it('C4-f: propuesta_enunciado corta o genérica es rechazada con status error', async () => {
      const f=await fixture();expect(isSubstantiveRuleText('Confirmar propósito y comportamiento esperado')).toBe(false);await f.working();const q=(await f.interview('catalog',{action:'next'})).question;const p=await f.interview('catalog',{action:'propose',question_id:q.id,version:q.version,expected_revision:0,proposal:{...f.proposal,description:'Confirmar propósito y comportamiento esperado'}});expect(await f.interview('catalog',{action:'review',question_id:q.id,version:p.question.version})).toMatchObject({status:'blocked',code:'substantive_statement_required'});expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);
    });
  });

  describe('C10: Detección y advertencia de extracción vacía', () => {
    it('C10-a: página app/login sin elementos interactivos genera advertencia extraccion_vacia y trabajo', async () => {
      const f=await fixture('<html><body><h1>Vista vacía</h1></body></html>');await f.working();const data=await f.call('qap_discover',{name:'catalog',path:'/catalog'});expect(data).toMatchObject({persistence:'committed',counts:{controls:0,forms:0}});expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);expect((await f.close('catalog',{action:'evaluate'})).assessment.specification_coverage.status).toBe('incomplete');
    });

    it('C10-b: página con al menos un elemento interactivo no genera advertencia extraccion_vacia', async () => {
      const f=await fixture();await f.working();const data=await f.discover();expect(data).toMatchObject({persistence:'committed',counts:{controls:expect.any(Number),forms:expect.any(Number)}});expect((await f.knowledge.query(f.scope.applicationId,'observation')).items.length).toBeGreaterThan(0);expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);
    });

    it('C10-c: la advertencia extraccion_vacia es agnóstica de la aplicación', async () => {
      const f=await fixture('<html><body><section>Sin acciones</section></body></html>');await f.working(['catalog','orders']);for(const module of ['catalog','orders']){const data=await f.call('qap_discover',{name:module,path:'/'+module});expect(data).toMatchObject({persistence:'committed',counts:{controls:0,forms:0}});expect(data).not.toHaveProperty('extraccion_vacia');}expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);
    });
  });

  describe('C3: Transliteración NFD de slugs y prevención de módulos fuera del plan', () => {
    it('C1-c: módulo con tilde preserva nombre en lifecycle, crea directorio y normaliza pending_questions con transliteración NFD', async () => {
      expect(normalizeSlug('Asignación de ejecutivo de campo por carga')).toBe('asignacion_de_ejecutivo_de_campo_por_carga');expect(normalizeSlug('Operación básica')).toBe('operacion_basica');const f=await fixture();await f.working(['catalog']);const before=readFileSync(f.lifecyclePath,'utf8');expect(await f.call('qap_discover',{name:'Operación básica',path:'/catalog'})).toMatchObject({status:'blocked',code:'module_restricted',persistence:'not_attempted'});expect(readFileSync(f.lifecyclePath,'utf8')).toBe(before);expect(f.lifecycle().modules).not.toHaveProperty('operacion_basica');
    });

    it('C2-seguimiento: selección de "Corregir" emite pregunta de seguimiento y no persiste regla espuria en rules.yaml', async () => {
      const f=await fixture();await f.working();const q=(await f.interview('catalog',{action:'next'})).question;const p=await f.interview('catalog',{action:'propose',question_id:q.id,version:q.version,expected_revision:0,proposal:f.proposal});const fixed=await f.interview('catalog',{action:'correct',question_id:q.id,version:p.question.version,expected_revision:0,proposal:{...f.proposal,description:'La consulta requiere datos vigentes del catálogo verificados.'}});expect(fixed).toMatchObject({status:'corrected',question:{id:q.id,human_review_required:true}});expect(fixed.question.version).toBeGreaterThan(p.question.version);expect((await f.knowledge.query(f.scope.applicationId,'requirement')).items).toHaveLength(0);expect(await f.interview('catalog',{action:'review',question_id:q.id,version:fixed.question.version})).toMatchObject({status:'blocked',code:'human_review_not_authorized'});
    });
  });
});
